#include <iostream>
using namespace std;

int main() {   //@ @layout open:visualizer
    int sum = 0;   //@ @tts [next] 先準備 sum
    for (int i = 1; i <= 8; i++) {   //@ @tts [next] 進入迴圈 | @2 [next] 下一圈
        sum += i;   //@ @guide {sum} @tts [fast @8] 前面七圈都快轉過去了，這是第八圈，sum 是 {sum}
    }
    cout << sum << endl;   //@ @tts [next] 全部跑完，總和是 {sum}
    return 0;   //@ @tts [continue] 程式結束
}
